<?php
require_once '../../config/auth.php';
requestMethod('POST');
$user=requireLogin();
$data=getRequestData(); $name=trim($data['landlord_name']??''); $addr=trim($data['property_address']??''); $districtRaw=$data['district_id']??$data['district']??''; $district=null; $stars=(int)($data['star_rating']??0); if($name===''||$addr===''||$stars<1||$stars>5) jsonError('Landlord name, address, and 1-5 rating are required.');
try{ $db=getDB(); if($districtRaw!==''){ if(is_numeric($districtRaw)) $district=(int)$districtRaw; else { $ds=$db->prepare('SELECT id FROM districts WHERE name=? LIMIT 1'); $ds->execute([$districtRaw]); $dr=$ds->fetch(); $district=$dr?(int)$dr['id']:null; } } $stmt=$db->prepare('INSERT INTO landlord_reviews (user_id,landlord_name,property_address,district_id,star_rating,is_recommended,review_text,is_approved) VALUES (?,?,?,?,?,?,?,0)'); $stmt->execute([currentUserId(),$name,$addr,$district,$stars,parseBool($data['is_recommended']??0),trim($data['review_text']??'')]); $id=(int)$db->lastInsertId(); $stmt=$db->prepare('INSERT INTO landlord_profiles (landlord_name,district_id,overall_rating) VALUES (?,?,0.00) ON DUPLICATE KEY UPDATE updated_at=CURRENT_TIMESTAMP'); $stmt->execute([$name,$district]); logActivity($db,currentUserId(),'submit_review','Submitted landlord review for '.$name); notifyAdmins($db,'system','New landlord review submitted by '.($user['name']??'a student').', pending approval.',$id); jsonResponse(['success'=>true,'review_id'=>$id]); }catch(Throwable $e){ jsonError('Could not submit review.',500); }
